<?php

declare(strict_types=1);

/**
 * English source-of-truth catalogue for candy-code's `crush` namespace
 * ({@see \SugarCraft\Code\Lang}). Every other `lang/<locale>.php` carries
 * exactly these keys with the same `{placeholders}` (tests/LangParityTest.php),
 * and every literal key `src/` asks for must exist here.
 *
 * Only text a PERSON reads lives here. Text the model reads — the system
 * prompt, tool descriptions and results, model-visible notices — protocol wire
 * values and log lines stay English in the code (LOCALES.md, candy-code row).
 * The generated docs read this catalogue but are always English: their
 * generators render under `Lang::inLocale('en', …)`, whatever the launch
 * locale is.
 *
 * The settings tabs come first; the rest is one block per area, each sorted
 * by key: `cli.` (the binary and its subcommands), `cmd.`/`keys.`/`settings.`
 * (the command, key-binding and settings registries), `chat.`/`host.` (the
 * session's notices, refusals and replies), `agents.` (a delegated run's live
 * trail) and `tui.`/`palette.` (the screen).
 *
 * After those blocks a tail carries feature additions: undated blocks
 * (serve remote, the session picker) sort by key like the main ones, while
 * dated `fix-*` waves — including the `appLaunch.*` notices Bootstrap prints
 * at launch — keep their own chronological grouping. The `settings.*.help`
 * catalogue (W3-B) joins the tail sorted by key.
 *
 * Copy conventions (pinned here; apply in this file, not at call sites):
 * - Brand: prose naming the product reads "CandyCode"; the binary a user
 *   types — and a running second instance — is "candy-code"; "candy-code"
 *   is only ever a path or directory name (~/.candy-code, the monorepo dir).
 * - Error labels: transcript-rendered error rows use the bold family
 *   '**Error:** {error}'. The one exception is 'chat.picker.error', an
 *   overlay notice that is not markdown-parsed, which stays plain 'Error: '.
 * - Placeholders: `{named}` tokens substituted with strtr are the default
 *   everywhere; printf `%s`/`%d` tokens appear only in the `cli.launch.*`
 *   launch-warning family, which renders through sprintf.
 * - Punctuation: a sentence stands alone with its period; short "X: Y"
 *   labels (usage lines, statuses, columns) carry none. Clause joins use the
 *   em dash " — ", never a bare hyphen " - ".
 * - Key notation: caret form (^C, ^P) is reserved for the width-bound
 *   status-bar cells that spell it; prose spells Ctrl+C / Ctrl+P.
 */
return [
