    'cmd.mcp-auth.disable.usage' => 'Usage: /mcp disable <server> [--persist]',
    'cmd.mcp-auth.empty' => "No stored MCP credentials.\n\nCredentials are only for servers that demand OAuth login; a\ndeclared http server that needs none runs from its \"url\" alone.\nServers themselves are declared under \"mcpServers\" in\n<project>/.mcp.json — recipe: docs/MCP.md, \"{section}\".",
    'cmd.mcp-auth.enable.done' => '✓ Enabled `{server}` for this session — session refusals lift from the next turn; calls are routed again only where launch routing already allows the name.',
    'cmd.mcp-auth.enable.no-client' => 'No MCP client this session — nothing to enable (no `.mcp.json` was trusted at launch).',
