    'cmd.mcp-auth.enable.persist-removed' => 'Removed `{server}` from the user disabledMcpServers list; launch no longer refuses it.',
    'cmd.mcp-auth.enable.unknown' => '! `{server}` is not a declared MCP server of this session — `/mcp list` shows the names.',
    'cmd.mcp-auth.enable.usage' => 'Usage: /mcp enable <server> [--persist]',
    'cmd.mcp-auth.failed' => '✗ Registration failed: {error}',
    'cmd.mcp-auth.heading' => '**MCP Servers**',
    'cmd.mcp-auth.login-armed' => "↻ MCP login started for `{server}` — watching for the browser link.\n\nThe child binds a loopback port; finish it in a browser while the TUI stays responsive. This session's MCP client memoized its store at launch, so the token takes effect at the NEXT launch; `/mcp list` shows the credential once it is stored.",
    'cmd.mcp-auth.login-busy' => '! A login for `{server}` is already running — finish or cancel that one first (its URL and status are in the transcript above).',
    'cmd.mcp-auth.login-code-delivered' => '✓ The callback was delivered to the waiting login for `{server}` — the child finishes the exchange there, and its result appears in the transcript.',
    'cmd.mcp-auth.login-code-refused' => '! Could not deliver the MCP login callback for `{server}`: {reason}',
    'cmd.mcp-auth.login-code-reason-dial' => "the waiting login's listener did not answer",
    'cmd.mcp-auth.login-code-reason-host' => 'only the loopback hosts `127.0.0.1` and `localhost` are accepted',
    'cmd.mcp-auth.login-code-reason-noslot' => 'no login for that server is currently waiting on this host',
    'cmd.mcp-auth.login-code-reason-port' => 'the port does not match the callback port the waiting login announced',
    'cmd.mcp-auth.login-code-reason-scheme' => 'the callback URL must use the plain `http` scheme the login listener binds',
    'cmd.mcp-auth.login-code-reason-shape' => 'the form is `/mcp login <server> --code <callback-url>` with exactly one URL',
    'cmd.mcp-auth.login-done' => '✓ MCP login for `{server}` finished (exit {code}). Tokens attach at the NEXT launch — start a new session for the grant to ride requests; `/mcp list` refreshes the panel.',
    'cmd.mcp-auth.login-failed' => <<<'TXT'
✗ MCP login for `{server}` exited {code} without storing tokens.

The child's last lines are above; the same flow in a shell (`candy-code mcp auth login {server}`) prints the full error and is the place to debug endpoint or port problems.
TXT,
    'cmd.mcp-auth.login-failed-spawn' => "✗ Could not start the MCP login child for `{server}`.\n\nRun the shell form directly: `candy-code mcp auth login {server}`.",
    'cmd.mcp-auth.login-guidance' => "Interactive login is a shell command, not a chat turn:\n\n  candy-code mcp auth login <server> [token-url] [authorize-url] [registration-url]\n\nIt runs the OAuth authorization-code flow with PKCE: your browser\nreturns the code to a loopback listener in the shell, and the stored\ntokens are attached to matching http servers from the next launch.",
    'cmd.mcp-auth.login-no-entry' => "✗ Could not find this program's own entry point to fork `mcp auth login {server}`.\n\nRun the shell form directly: `candy-code mcp auth login {server}`.",
    'cmd.mcp-auth.login-served-armed' => "↻ MCP login started for `{server}` on the SERVER host — its link arrives below; open it in a browser on your own machine. Your browser cannot reach the server's loopback listener directly: when it lands on a connection-error page, copy that page's address and send `/mcp login {server} --code <that-url>` to hand the callback to the waiting login. Tokens attach at the NEXT launch; `/mcp list` shows the credential once it is stored.",
    'cmd.mcp-auth.login-url' => '→ Open this URL to authorize `{server}`:\n\n  {url}',
    'cmd.mcp-auth.not-found' => '! No credentials found for `{server}`.',
    'cmd.mcp-auth.registered' => <<<'TXT'
✓ Successfully registered `{server}`
Client ID: `{client}`
Requests to an http MCP server with this exact URL now carry this token automatically, refreshed before expiry; servers started before this command pick it up on the next launch.
TXT,
    'cmd.mcp-auth.remove-usage' => 'Usage: mcp auth remove <server>',
    'cmd.mcp-auth.reconnect.auth' => '! `{server}` now reports that it needs an OAuth login.',
    'cmd.mcp-auth.reconnect.denied' => '! `{server}` is refused by a deny pattern.',
    'cmd.mcp-auth.reconnect.drifted' => "MCP config changed since launch — reconnect refused. A reconnect restarts the servers exactly as `.mcp.json` holds them now, while this session was admitted against the bytes launch trusted; starting drifted entries would run servers the admission decisions never saw. Restart the session to apply the change; that is the only apply path.",
    'cmd.mcp-auth.reconnect.error' => 'Starting failed: {error}',
    'cmd.mcp-auth.reconnect.heading' => '**Reconnected MCP servers**',
    'cmd.mcp-auth.reconnect.no-client' => 'No MCP client this session — nothing to reconnect (no `.mcp.json` was trusted at launch).',
    'cmd.mcp-auth.reconnect.none' => 'no servers are started for this session',
    'cmd.mcp-auth.reconnect.refused' => '! `{server}` was refused at admission (trust pin mismatch or an unknown entry).',
    'cmd.mcp-auth.reconnect.state.down' => 'down',
    'cmd.mcp-auth.reconnect.state.starting' => 'starting',
    'cmd.mcp-auth.reconnect.state.up' => 'up',
    'cmd.mcp-auth.reconnect.tool-drift' => 'offers {now} tools; this session was built with {was} — the model-facing roster is not re-derived mid-session, start a new session to adopt them',
    'cmd.mcp-auth.reconnect.unknown' => 'This session recorded no launch digest for `.mcp.json`, so a reconnect cannot prove the config still holds the bytes launch started from — refused, restart is the only apply path.',
    'cmd.mcp-auth.removed' => '✓ Removed credentials for `{server}`',
    'cmd.mcp-auth.status.active' => '● active',
    'cmd.mcp-auth.status.expired' => '○ expired',
    'cmd.mcp-auth.status.expiring' => '● expiring soon',
    'cmd.mcp-auth.status.none' => '○ no credentials',
    'cmd.mcp-auth.undiscovered' => "! OAuth endpoints could not be discovered for `{server}`.\n\nPlease provide them explicitly:\n  `mcp auth add {server}` *<registration-url>* *<token-url>*\n\nNothing to discover usually means nothing to register: a\nserver that needs no login runs from its \"url\" alone once\ndeclared in .mcp.json (docs/MCP.md, \"{section}\").",
    'cmd.mcp-auth.unknown' => 'Unknown sub-command \'{sub}\'. Use: list, add, remove, login, reconnect, enable, disable',
    'cmd.mcp-auth.usage' => "Usage:\n  mcp auth list                    — list registered servers\n  mcp auth add <server> [reg-url] [token-url]  — store OAuth credentials for a server\n  mcp auth remove <server>         — remove a server's credentials\n  mcp auth login <server>          — print the shell command for interactive login\n  /mcp reconnect                   — restart the declared servers, only while .mcp.json still matches launch\n  /mcp enable <server> [--persist]   — lift this session's refusal of a declared server\n  /mcp disable <server> [--persist]  — refuse a declared server's calls for this session",
    'cmd.mcp.description' => 'Manage MCP server auth (list/add/remove; login prints the CLI command) and session enable/disable',
    'cmd.mcp.hint' => '<list|add|remove|login|reconnect|enable|disable> [server]',
