    // --- settings help (W3-B i18n migration) ---
    'settings.allowedTools.help' => 'Whitelist of tool names or globs; unset offers every tool.',
    'settings.attribution.help' => '{"commit": "…", "pr": "…"}: the trailer and PR line the git guidance asks for.',
    'settings.autoCommit.help' => 'off, turn (one commit per turn, message from the title model) or edit (one per Write/Edit); /undo reverts it.',
    'settings.autoReview.help' => 'Under auto, a call the safety classifier flags (other than a security finding, which always asks) is reviewed by the title model, which allows it, asks you or denies it.',
    'settings.autoReviewModel.help' => 'The `provider/model` the auto reviewer runs on, for example `openai/gpt-4.1-mini`; empty means the title model. A provider that cannot be built leaves the reviewer off with a launch warning.',
    'settings.autoReviewScope.help' => 'What `autoReview` sends to the reviewer: `shell` (the default) is every non-read-only shell command the pattern list passed; `writes` also reviews `Edit`, `Write`, `ApplyPatch` and `WebFetch`, with the pending diff for the write tools; `all` reviews every call the list passed. Any other spelling behaves as `shell`. Every review is a paid model call.',
    'settings.autoTest.help' => 'After a turn that edited a file, run `testCommand`; on failure the output goes back to the model, at most 3 times a turn.',
    'settings.bashInteractiveIdleSeconds.help' => 'Seconds an `interactive: true` Bash run may print nothing before it is stopped as waiting for a keystroke.',
    'settings.bashMaxTimeoutSeconds.help' => 'The largest `timeout` a Bash command may ask for; larger values are clamped to it.',
    'settings.bashSandbox.help' => 'Linux only: run Bash inside bubblewrap, writable only in the working root (`no-network` also cuts the network). Refuses commands when bwrap cannot start.',
    'settings.bashTimeoutSeconds.help' => 'Seconds a Bash command may run when the model passes no `timeout`; never above the Bash ceiling.',
    'settings.chatToolTimeoutSeconds.help' => 'Wall-clock budget of a batch of tool calls the chat-native (`command` provider) path forks; stragglers are killed.',
    'settings.claudeMcpArgs.help' => 'Arguments for that binary; unset uses the transport default.',
    'settings.claudeMcpBinary.help' => 'Absolute path of the `claude` binary the claude-mcp transport may spawn.',
    'settings.claudeMcpEnv.help' => 'Literal environment variables handed to that binary.',
    'settings.compaction.autoPercent.help' => 'Window share at which older exchanges are condensed automatically before the prompt is sent.',
    'settings.compaction.autoTokens.help' => 'Absolute cap on the automatic tier and the in-turn step budget. 0 turns the cap off.',
    'settings.compaction.blockPercent.help' => 'Window share past which a prompt is refused until space is freed; the only tier that refuses.',
    'settings.compaction.blockTokens.help' => 'Absolute cap on the blocking tier; unset by default. Setting it lets a cap refuse prompts.',
    'settings.compaction.idleAuto.help' => 'Compact an idle over-tier session during the idle instead of waiting for the next prompt, using the automatic tier\'s machinery (spend cap and thrash breaker apply). off: never; hour: after the full compaction.idleOfferSeconds window; cacheTtl: just short of the provider\'s prompt-cache expiry — an hour when the provider marks cache breakpoints, about 5 min for server-side caches, never where it reports nothing cached — once the history is over a floor below the automatic tier, because the next prompt would otherwise prefill the whole conversation uncached; on the 60-second tick a 5-min cache folds at roughly 4 minutes idle. Costs a background provider call; needs compaction.idleOfferSeconds above 0. A bool keeps reading: true means hour, false means off.',
    'settings.compaction.idleOfferSeconds.help' => 'A session past its whole context window that sat untouched this long is offered /compact instead of sending the prompt. 0 never offers.',
    'settings.compaction.keepRecent.help' => 'Most recent user/assistant exchanges a compaction keeps in full.',
    'settings.compaction.mode.help' => 'llm: the summary model writes the summaries (the heuristic is its fallback); heuristic: local one-line summaries, never a model call; off: nothing compacts on its own, /compact still works and the blocking tier still refuses.',
    'settings.compaction.modelTokenCaps.help' => '{"<model>" or "<provider>/<model>": {"reminderTokens", "autoTokens", "blockTokens"}} overriding the three caps; 0 clears one.',
    'settings.compaction.refillLimit.help' => 'Automatic compactions in a row that may come straight back over their tier, prompt unsent, before the next prompt is refused instead of compacted again.',
    'settings.compaction.reminderPercent.help' => 'Window share at which the "consider compacting" reminder and the ahead-of-need background summary start; below the automatic tier.',
    'settings.compaction.reminderTokens.help' => 'Absolute cap on the reminder tier: it fires at min(percentage, this). 0 turns the cap off.',
    'settings.compaction.summaryAssistantChars.help' => 'Assistant replies longer than this become "[exchanged information]" in a heuristic summary line.',
    'settings.compaction.summaryUserChars.help' => 'Characters of a user message the heuristic summary line keeps.',
    'settings.compaction.toolOutputChars.help' => 'Characters of a condensed exchange\'s assistant half the summariser model is shown.',
    'settings.connectTimeoutSeconds.help' => 'Bound on reaching a provider host (DNS, TCP, TLS); not a request timeout.',
    'settings.contextPruning.compress.help' => 'manual offers Compress only on a turn you start with /compress, one call; auto offers it on every turn where the model may prune.',
    'settings.contextPruning.iterationNudgeThreshold.help' => 'Tool results since the last prompt after which a long tool loop is reminded to prune.',
    'settings.contextPruning.maxContextTokens.help' => 'Context size above which the newest row carries the stronger "prune now" reminder.',
    'settings.contextPruning.minContextTokens.help' => 'Context size below which the model is never reminded to prune; must not exceed the hard-reminder size.',
    'settings.contextPruning.mode.help' => 'auto prunes superseded rows at each turn start; manual only on /sweep; off shows no ref tags. /pruning overrides it per session.',
    'settings.contextPruning.nudgeFrequency.help' => 'New rows a reminder waits for after the last one, so it does not repeat on every step.',
    'settings.contextWindow.help' => 'Token window override: a count for the provider\'s model, or {"<model>": tokens}.',
    'settings.debug.commands.help' => 'Put each refused custom-command directory or file on stderr, not only the launch\'s one-line count.',
    'settings.debug.rules.help' => 'Put each refused rules directory or file on stderr.',
    'settings.debug.skills.help' => 'Put each skipped skill file and refused skills directory on stderr, not only the launch\'s one-line count.',
    'settings.debug.stream.help' => 'Put the "onToken observer threw, detaching it" line on stderr when an embedder\'s streaming sink fails mid-turn.',
    'settings.diffPreviewRows.help' => 'Rows of an Edit or Write diff shown in the transcript before the rest is summarised.',
    'settings.diffStyle.help' => 'Diff layout in the transcript: `auto` paints hunks side-by-side on wide terminals (120 columns or more) and unified elsewhere, `unified` always one column, `split` always two. Diff bodies are tinted per token in either layout; the `+`/`-` marker column keeps its colour.',
    'settings.disabledMcpServers.help' => '`.mcp.json` server names or globs (`untrusted_*`) that are never started, listed or called, for the main agent and every sub-agent.',
    'settings.disabledRules.help' => 'User-tier rule packs kept out of the prompt from the first turn.',
    'settings.disabledSkills.help' => 'Skills removed from discovery; also wins over enabledSkills.',
    'settings.disabledTools.help' => 'Tool names or globs removed from the model-facing tool set.',
    'settings.doubleEscSeconds.help' => 'How quickly the second Esc must follow the first to cancel a running turn.',
    'settings.embeddingModel.help' => 'Embedding model for the per-turn memory recall; unset ranks notes by keyword only.',
    'settings.enabledSkills.help' => 'Skills whose full bodies ride the system prompt every turn.',
    'settings.env.diffMaxBytes.help' => 'Bytes each of the two git diff sections keeps before it is truncated with a note.',
    'settings.env.gitDiffAfterWrites.help' => 'After a step that wrote files, show the staged and unstaged git diffs in the turn context.',
    'settings.expandToolOutput.help' => 'Show each finished tool call\'s output in full in the transcript; Ctrl+O or a click still collapses one.',
    'settings.extraBody.help' => 'Top-level request fields added to every `custom` provider request.',
    'settings.formatCommands.help' => 'Post-edit format command per file extension ({"php": "vendor/bin/php-cs-fixer fix {file}"}); runs before the post-edit lint and rewrites the file. Off by default.',
    'settings.formatAuto.help' => 'Let the built-in extension table (gofmt, rustfmt, ruff/black, shfmt, terraform fmt, the project\'s own node_modules prettier) format an edited file when `formatCommands` names no command for its extension. Explicit entries win; a project still needs `trustedProjectHooks`. Off by default.',
    'settings.globMaxMatches.help' => 'Paths one Glob collects before its walk stops; the output cap still bounds the result.',
    'settings.grepTimeoutSeconds.help' => 'Seconds one Grep search may run before it is killed; hits found up to the deadline come back as a partial result.',
    'settings.hooksDefaultTimeoutSeconds.help' => 'Seconds a hook entry with no `timeout:` may run before it is killed and counted as a refusal.',
    'settings.includeGitInstructions.help' => 'Whether the Bash tool\'s generic commit guidance rides the system prompt.',
    'settings.instructions.help' => 'Globs of files whose contents become authoritative system-prompt text.',
    'settings.instructions.walkToRoot.help' => 'Opt-in: also read instruction files above the nearest .git marker, up to but not including the home directory. User-tier only; every read keeps its containment and size budget.',
    'settings.instructionsExclude.help' => 'Globs of instruction files to skip, recorded as refusals; user-tier only — a repository cannot mute its operator. Files inside the checkout match by checkout-relative path; ancestor and forced files outside it match by absolute path, so `**/CLAUDE.local.md` reaches the ancestor copies too.',
    'settings.keybindings.help' => '{"shell.palette": "Ctrl+B"}: bind an EXTRA chord to a binding id (the /keys reference names them) — Ctrl+<key>, Alt+<key>, Shift+<key>, or a lone function key; the shipped chord keeps working. Present-but-unusable refuses the launch; remove the key for the shipped bindings.',
    'settings.layout.help' => 'The docked-pane manifest; written by the shell when panes move.',
    'settings.lintCommands.help' => 'Post-edit lint command per file extension ({"php": "…", "js": false}); `php -l` is built in.',
    'settings.lsp.help' => '{"php": {"command": "intelephense", "args": ["--stdio"]}}: servers for post-edit diagnostics, Read outlines and the Lsp tool.',
    'settings.lspAutoDetect.help' => 'Start the language server a project fingerprint names (composer.json → intelephense, package.json + tsconfig.json → typescript-language-server, pyproject.toml or setup.py → pyright-langserver, go.mod → gopls, Cargo.toml → rust-analyzer) when its binary is on PATH; manual `lsp` entries win per language. Launching a server runs that server and the build code in the opened tree, so fingerprints start servers only in projects you have trusted for hooks; an untrusted root starts none and records the skip in the launch notices.',
    'settings.maxCheckpoints.help' => 'Turn checkpoints /rewind can return to, per session; the oldest are pruned past this.',
    'settings.maxCostUsd.help' => 'Refuse new turns once the provider-reported spend of a launch reaches this many US dollars; unset is no cap. /budget changes it for the running launch only.',
    'settings.maxOutputTokens.help' => 'Per-request output ceiling; unset sends no override and the provider default applies.',
    'settings.maxToolSteps.help' => 'Provider calls one turn may make; unset keeps the engine default.',
    'settings.mcp.enabled.help' => 'Start the MCP servers a trusted project\'s .mcp.json names; off starts none and the surfaces report the launch as disabled.',
    'settings.mcp.lazySchemaTokens.help' => 'Schema tokens one MCP server may advertise before its tools defer to mcp_list/mcp_call; 0 never defers.',
    'settings.mcpResultCapBytes.help' => 'Most bytes one MCP tool\'s answer may hand the model.',
    'settings.memory.autoConsolidate.help' => 'Save durable facts from finished turns into memory, and fold the compaction journal into it (the dream pass); each is a billed call.',
    'settings.memory.dreamIntervalSeconds.help' => 'Least time between two dream passes for one project; each pass is a billed, read-only turn.',
    'settings.memory.dreamProposeSkills.help' => 'Let the dream pass propose skills as drafts in ~/.candy-code/skills-proposed; none is live until you /skills accept it.',
    'settings.memory.entryMaxBytes.help' => 'Longest one note\'s index line may be before it is shown truncated; lowered to the user-note budget if over it.',
    'settings.memory.projectNoteMaxBytes.help' => 'Largest one project memory note may be when it is written to the repository\'s .candy-code/memory/.',
    'settings.memory.promptMaxBytes.help' => 'Byte budget for the memory index\'s note lines; the user-note budget is lowered to fit inside it.',
    'settings.memory.promptMaxEntries.help' => 'Most notes the prompt\'s memory index lists, newest first; user notes count inside it.',
    'settings.memory.userMaxBytes.help' => 'Byte budget for the user-scope lines, inside the total budget.',
    'settings.memory.userMaxEntries.help' => 'Most of your cross-project (user-scope) notes listed first, inside the note count.',
    'settings.modelPrices.help' => 'USD per 1M tokens per model ({"input": …, "output": …}), for the spend total and cap.',
    'settings.models.help' => 'The model to run, per provider ({"<provider>": "<model id>"}); unset uses the provider default.',
    'settings.mouse.help' => 'Report the mouse to candy-code (clicks, wheel, selection); off gives the terminal its own copy-on-select back.',
    'settings.mouseClicks.help' => 'Clicks and drags act on what they hit; off keeps the wheel and ignores clicks.',
    'settings.notices.transcriptLimit.help' => 'Most launch warnings seated as transcript rows; the rest are counted in one "and N more" row, and stderr carries them all.',
    'settings.notify.help' => 'off, bell (BEL) or osc9 (a desktop notification): sent when a turn ends and when the agent waits for an approval.',
    'settings.paletteMru.help' => 'How many recently used palette rows are remembered and ranked first; 0 remembers none.',
    'settings.parallelToolCalls.help' => 'Run a turn\'s read-only tool calls concurrently.',
    'settings.parallelToolDeadlineSeconds.help' => 'Wall-clock ceiling for one batch of concurrently dispatched tool calls.',
    'settings.permissionMode.help' => 'How tool calls are gated. Never taken from a project file.',
    'settings.permissionRules.help' => 'Ordered allow / deny / ask rules matched against each tool call. A trusted project’s shared settings.json may contribute deny / ask entries — narrowing only.',
    'settings.permissions.autoAllowReadOnly.help' => 'Under default and accept-edits, run a Bash line made only of read-only commands (ls, cat, grep, git log, …; no file redirection, no substitution, cd only inside the project) without asking. A project may only switch it off.',
    'settings.permissions.autoStrikeLimit.help' => 'Under auto, this many blocked calls of one category in a row turn the next one into a question.',
    'settings.permissions.autoTotalLimit.help' => 'Under auto, once this many calls have been blocked in a session every further block asks you instead.',
    'settings.pluginPaths.help' => 'Extra directories scanned for Claude-format plugin bundles, beside the two installed roots; a value may name a bundle itself or a container of bundles. User-tier only — a checkout cannot enroll its own plugins.',
    'settings.promptCache.help' => 'Whether the `vertex` and `bedrock` providers mark prompt-cache breakpoints.',
    'settings.promptSuggestionHistory.help' => 'Recent messages (each clipped to 2000 characters) the prompt-suggestion call is shown.',
    'settings.promptSuggestions.help' => 'After each turn, ask the title model for the message you are likely to send next and show it greyed in the empty input box (→ accepts it).',
    'settings.provider.help' => 'Which LLM provider the session talks to; every prompt is sent to its host.',
    'settings.providerRetryAttempts.help' => 'Calls per provider request when it fails transiently (network, 5xx, 408, 429), the first included; 1 never retries.',
    'settings.providerRetryBaseBackoffMs.help' => 'Wait before the first retry of a failed provider call; each later wait doubles.',
    'settings.providers.help' => 'Provider definitions per name ({"<name>": {"type": …, "baseUrl": …, "apiKey": …, "model": …}}); each entry layers over that type\'s defaults. User tier only: a project must never move where your credential is sent.',
    'settings.queueMode.help' => 'steer (the agent reads it at its next step), followup (sent after the turn) or interrupt (stop the turn at its next step, then send). Tab always queues.',
    'settings.readMaxBytes.help' => 'Ceiling on one Read call; the page below is the size a read usually comes back at.',
    'settings.readPageBytes.help' => 'Bytes one Read page may hold, line numbers included, whatever `limit` asks for.',
    'settings.readPageLines.help' => 'Lines a Read returns when the call names no `limit`.',
    'settings.reasoningEffort.help' => 'Thinking tier sent where the pair shapes it: openai (o-series and gpt-5, not the -chat builds), anthropic and vertex (claude-3-7 and newer; vertex answers on both its claude and gemini arms), gemini (2.5 and newer), sglang (forwarded on every request), bedrock (claude ids, as a thinking budget), codex and claude-code (named tiers forwarded to the CLI); unset or unrecognized asks nothing. `/effort` sets and clears it.',
    'settings.references.help' => 'A list of `[{"path": "…", "name": "…"}]` directories outside the workspace that Read, Grep, Glob and Ls may also open, read-only; each one is advertised in the `<env>` block with a capped map of what lives there. The workspace jail is unchanged for Write, Edit and Bash — a reference never widens what can be written. User tier only: a checked-out repository cannot add a read root. A missing or non-directory path, or one inside the session root, is refused at launch with a notice.',
    'settings.repoMap.enabled.help' => 'Put the map of where code lives (packages and PSR-4 source directories) in the system prompt.',
    'settings.repoMap.maxBytes.help' => 'Byte budget for each of the repo map\'s two sections; entries past it are counted, not listed.',
    'settings.requireReadBeforeWrite.help' => 'On, `Edit`, a `Write` that overwrites an existing file, and an `ApplyPatch` section that changes, moves or deletes one all refuse until the model has read that file in this session; creating new files is never blocked. Off by default: files the model did read stay guarded by the changed-on-disk rule either way.',
    'settings.rules.standingMaxBytes.help' => 'Byte budget, framed and escaped, for the rule files spliced whole into every prompt; a rule past it is named by one pointer line instead.',
    'settings.scrollWheelLines.help' => 'Transcript lines one wheel tick scrolls.',
    'settings.sd.apiKey.help' => 'Bearer key sent to the Stable Diffusion server, if it demands one; prefer the `${VAR}` placeholder form over a literal.',
    'settings.sd.baseUrl.help' => 'HTTP base URL of an AUTOMATIC1111-compatible Stable Diffusion webui (`http://127.0.0.1:7860`); prompts, images and the API key all egress there.',
    'settings.sd.defaultModel.help' => 'Model id generation requests start with; the server keeps the pick to itself when unset.',
    'settings.sd.presets.help' => 'Named parameter bundles the media form offers; the shape is the media pipeline\'s own, opaque to the settings layer.',
    'settings.sd.savePattern.help' => 'File name template for saved media; the `[date]`, `[time]`, `[seed]` and `[number]` tokens fill at save time.',
    'settings.sd.timeoutSeconds.help' => 'Seconds one generation request may run before it is abandoned; diffusion on a weak GPU routinely takes minutes.',
    'settings.secretEnvAllowlist.help' => 'Credential-shaped variable names (or globs) Bash, Grep and script hooks still inherit.',
    'settings.server.allowBypass.help' => 'Whether server sessions may run in bypass-permissions or dont-ask (same as --allow-bypass).',
    'settings.server.allowedHosts.help' => 'Host names (or host:port) the server answers to beside the loopback names and its own addresses, e.g. a reverse proxy\'s.',
    'settings.server.allowedIps.help' => 'Client IPs or CIDR ranges allowed to connect beside loopback; anyone else is refused 403 before sign-in. Empty: no address filter.',
    'settings.server.allowedOrigins.help' => 'Extra browser origins (http(s)://host[:port]) the server accepts beside its own.',
    'settings.server.askTimeoutSeconds.help' => 'Seconds a permission question waits for a client before it is refused; 0 waits forever.',
    'settings.server.browseRoot.help' => 'The directory server.dirBrowse is confined to (same as --browse-root); unset is your home directory.',
    'settings.server.dirBrowse.help' => 'Let signed-in clients list directory names under server.browseRoot and start sessions there (same as --allow-dir-browse). Off by default.',
    'settings.server.drainSeconds.help' => 'Seconds a stopping server waits for running turns before cancelling them; 0 stops at once.',
    'settings.server.host.help' => 'The address `serve` binds. Anything but loopback also needs --allow-remote at launch.',
    'settings.server.maxConcurrentTurns.help' => 'Turns a server runs at once across its sessions; one more is refused busy (retryable).',
    'settings.server.maxOpenSessions.help' => 'Sessions a server keeps open at once; past it the least recently used idle one is released.',
    'settings.server.port.help' => 'The port `serve` binds; 0 picks a free one.',
    'settings.server.trustedProxies.help' => 'IPs or CIDRs whose X-Forwarded-For / X-Forwarded-Proto the server believes.',
    'settings.serviceTier.help' => 'Premium lane sent where the pair shapes it: openai asks `service_tier: "priority"` on both its Chat and Responses arms, anthropic asks `speed: "fast"` (only the claude-opus-5-5 GA family and the claude-opus-5 / claude-opus-4-8 research-preview families, whose required beta header rides automatically); unset or unrecognized asks nothing. Fast mode bills a premium no model-keyed price table can derive: while a tiered pair is live its turns land on the ledger as unpriced, never as a guessed rate. Applies at launch and on every provider or model rebuild.',
    'settings.sessionRetentionDays.help' => 'Each launch deletes unnamed, unpinned sessions untouched for this many days and says which; 0 (the default) keeps everything.',
    'settings.sessions.autoTitle.help' => 'Name each new session from its first turn with one call on the title model; off leaves it unnamed until /rename.',
    'settings.skills.listingMaxBytes.help' => 'Byte budget for the whole skill listing in the system prompt; skills past it collapse into one "N more skills" line.',
    'settings.skills.pathNudges.help' => 'When a tool touches a file a path-scoped skill covers, remind the model that skill exists, once per skill.',
    'settings.statusLine.help' => '{"type": "command", "command": "…", "refreshSeconds": 2}: a shell command whose output paints the status bar, re-run every refreshSeconds (2 to 3600, default 2).',
    'settings.streamHeaderTimeoutSeconds.help' => 'Seconds a connected streaming server may take to send its response headers; never a total request timeout.',
    'settings.streamIdleTimeoutSeconds.help' => 'Seconds one read of a streaming reply may wait for bytes before the connection is called dead; per read, never a total.',
    'settings.subagentMaxActive.help' => 'Delegated runs one session may have going at once, every level, member and background agent counted; past it a `Task` call is refused. Unset — the default — or 0 sets no cap.',
    'settings.subagentMaxConcurrent.help' => '`Task` calls of one batch that run at once (the rest wait for a free slot), and the width of every agent pool. Unset — the default — or 0 sets no cap.',
    'settings.subagentMaxDepth.help' => 'Levels below the session a delegated run may be; a run at the last level gets no `Task`. 1 lets sub-agents delegate no further.',
    'settings.subagentMaxTurns.help' => 'Step cap for a sub-agent — a `Task` delegation, a workflow stage or an `executeAgents` run — whose preset declares no `maxTurns`.',
    'settings.subagentModel.help' => 'Model a delegated sub-agent runs on when its preset says `inherit`; unset follows the session\'s model.',
    'settings.summaryModel.help' => 'Model that writes compaction summaries; unset uses the conversation\'s own model, which reuses the prompt cache.',
    'settings.symbolMap.enabled.help' => 'Put the ranked symbol-level repo map in the system prompt, captured once per session.',
    'settings.temperature.help' => 'Sampling temperature the `custom` provider sends when a request names none.',
    'settings.terminalBackground.help' => 'What the adaptive theme assumes behind the text: auto asks the terminal (OSC 11, then COLORFGBG); light or dark says so outright.',
    'settings.testCommand.help' => 'Shell command that runs the project\'s tests, in the project root (`composer test`, `pytest -q`); what `autoTest` runs.',
    'settings.theme.help' => 'Colour theme; /theme and the palette change it live.',
    'settings.thinkingBudget.help' => 'Thinking-token budget: Gemini `thinkingConfig` on the `vertex` provider; extended thinking on the `anthropic` provider, where the Messages API floor is 1024 (0 or unset means off on either arm). Thinking tokens bill as output.',
    'settings.titleModel.help' => 'Model that names sessions and writes prompt suggestions; unset uses the provider type\'s cheap auxiliary default before the block model.',
    'settings.toolInstructionCapBytes.help' => 'Most bytes of a governing CLAUDE.md/AGENTS.md body an Edit, Write or ApplyPatch result may carry; the rest is cut with a marker.',
    'settings.toolOutputCapBytes.help' => 'Most bytes one Bash, Grep, Glob, Lsp or WebFetch result may hand the model; what is cut is saved to a file the result names.',
    'settings.toolOutputPreviewLines.help' => 'Lines of a collapsed tool result shown in the transcript; Ctrl+O expands the rest.',
    'settings.toolSpillCaptureBytes.help' => 'Most of a Bash command\'s output (per stream) held in memory and saved to the spill file when the result is cut; never below the output cap.',
    'settings.toolSpillMinCapBytes.help' => 'Smallest result cap at which a cut tool result is saved to a file; under it the cut is announced and the rest dropped.',
    'settings.toolSpillWindowPercent.help' => 'Largest share of the context window one tool result may take; past it the result is saved to a file and the model shown its start and end.',
    'settings.trustedProjectCommands.help' => 'Project roots whose slash commands may run !`cmd` shell blocks.',
    'settings.trustedProjectHooks.help' => 'Project roots whose .candy-code/hooks.yaml may run.',
    'settings.trustedProjectMcp.help' => 'Project roots whose .mcp.json servers may be launched.',
    'settings.trustedProjectSettings.help' => 'Project roots whose .candy-code/settings*.json may set the project-tier keys.',
    'settings.turnIdleTimeoutSeconds.help' => 'Seconds a running turn may go without any progress before it is stopped as hung; idle time, never a total.',
    'settings.ui.imageRenderMode.help' => 'How generated images are painted in the terminal; `auto` picks the best protocol the terminal reports.',
    'settings.ui.mediaDisplayOverrides.help' => 'Per-render-mode display tweaks (size caps, fallbacks); keys are the render-mode words, the values the display knobs.',
    'settings.vimMode.help' => 'NORMAL/INSERT editing in the draft box (i a I A o O Esc, h j k l w b e 0 $ x, dd D cc C yy y p P v V, text objects di" da( ciw, counts 3dd d2w): motions, change, deletion and yank in NORMAL, verbatim typing in INSERT. A mode, not bindings — it never appears in /keys. Applies on the next keystroke after saving.',
    'settings.watchFiles.help' => 'Send a prompt when a saved file holds a comment ending in AI! (make a change) or AI? (answer a question); plain AI comments ride along as context. Polled while the chat is idle; only comments saved after launch fire, each once. Terminal sessions only: the watcher runs in the terminal process, so a session hosted by `candy-code serve` does not watch files.',
    'settings.webFetchMaxBytes.help' => 'Most of a fetched body held in memory; a memory bound, the output cap is what reaches the model.',
    'settings.webFetchTimeoutSeconds.help' => 'Seconds a WebFetch socket read may stall before the fetch fails.',
    'settings.webSearchBackend.help' => 'Which search service WebSearch queries: `searxng` (the default) sends every query to the configured `webSearchEndpoint`; `brave`, `tavily` and `exa` dial that service\'s fixed host instead and each needs its API key in the environment (`BRAVE_SEARCH_API_KEY`, `TAVILY_API_KEY`, `EXA_API_KEY`), with no way to point them at another URL.',
    'settings.webSearchEndpoint.help' => 'Search URL of a SearXNG instance you trust (`https://searx.example.org/search`); every WebSearch query is sent there.',
    'settings.webSearchMaxResults.help' => 'Results one WebSearch digest lists, each a title, URL and snippet.',
    'settings.webSearchTimeoutSeconds.help' => 'Seconds one search request may take.',
    'settings.webhooks.help' => 'Map of hook name to {secret, prompt, permissionMode?, rate?}; POST /api/hooks/{name} then splices the body (escaped as untrusted) into the prompt and starts a background session. Empty (default) mounts nothing. rate is N deliveries per minute per address, and per hook overall. bypass-permissions is refused for hooks at launch; a mode-less hook runs in the stricter of the server mode and default. A row may also name signature: {scheme: "github-sha256"|"hmac-sha256", header?, deliveryHeader?}: the route then verifies an HMAC-SHA256 of the raw body (sha256=<hex>) with the row secret through the signature header, in place of the custom header secret, because GitHub cannot send custom headers; failed signatures feed the same per-hook lockout, and a delivery id already seen (X-GitHub-Delivery by default for the GitHub scheme; the configured deliveryHeader for a generic one) answers {"ok": true, "duplicate": true} without starting a second session.',
    'settings.webhooksOut.help' => 'Map of endpoint name to {url, secret, events}; events is a non-empty list drawn from turn.completed, session.ended, permission.asked and schedule.fired. Empty (default) opens no egress at all. Read from the USER tier only \u2014 a project or bundle config can never add an outbound endpoint. url must be https, or http only when its literal host is localhost or a loopback address, and never carries userinfo; secret is at least 16 characters and HMAC-SHA256-signs each delivery as X-Candy-Code-Signature (sha256=<hex> over the exact body) paired with X-Candy-Code-Timestamp. Delivery is asynchronous on the event loop \u2014 dispatches never wait for a response: a 2-second connect boundary and a 10-second per-POST network cap bound each delivery (webhook bounds, not an LLM request timeout), failed transports and 5xx answers climb a 2/8/30-second retry ladder, 4xx and redirect answers are final the first time because redirects are refused rather than followed, and a bounded queue of 128 in-flight deliveries drops new dispatches on overflow rather than growing memory. Read at launch; changing the map takes effect on restart.',
    'settings.webhooksOut.refuse' => 'webhooksOut in the user config is unusable: {reason}. Refusing to start rather than deliver to a half-checked endpoint — fix the map, or remove the key to run without outbound webhooks.',
    // --- end settings help ---

